// Fireflies: N blinking agents drift around the lamp in (angle, height) space.
// All per-LED math is fixed point; agents are simulated once per frame in update().
uniform float speed : 0.0 .. 5.0 = 1.0;     // global drift + twinkle rate
uniform float density : 0.0 .. 1.0 = 0.6;   // fraction of flies awake
uniform float glow : 0.0 .. 3.0 = 1.4;      // flash brightness
uniform float warmth : 0.0 .. 1.0 = 0.65;   // hue mix green -> amber
uniform vec3 tint : color = 1.0, 0.85, 0.55;

state fixed flies[16];   // packed Q8.8: [0]=y, [1]=ang, [2]=vy, [3]=w, [4]=seed
state fixed head;        // integrated global phase (turns)
state fixed fspd;
state fixed fdens;
state fixed fglow;
state fixed fwarm;
state fixed fr, fh, ftwo;
state bool inited;

void update() {
  if (!inited) {
    for (int i = 0; i < 16; i = i + 1) {
      fixed sd = fixed(hash(float(i) * 7.31));
      flies[i * 5 + 0] = fract(sd * fixed(0.713));
      flies[i * 5 + 1] = fract(sd * fixed(0.377) + fixed(0.25));
      flies[i * 5 + 2] = (fract(sd * fixed(0.531)) - fixed(0.5)) * fixed(0.06);
      flies[i * 5 + 3] = fract(sd * fixed(0.917));
      flies[i * 5 + 4] = sd;
    }
    inited = true;
  }
  head = fract(head + fixed(dt) * fixed(speed));
  fspd = fixed(speed);
  fdens = fixed(density);
  fglow = fixed(glow);
  fwarm = fixed(warmth);
  fr = fixed(0.08);
  fh = fixed(0.30);
  ftwo = fixed(2.0);
  for (int i = 0; i < 16; i = i + 1) {
    fixed sd = flies[i * 5 + 4];
    fixed wob = sin(head * ftwo + sd * fixed(6.2832));
    flies[i * 5 + 0] = fract(flies[i * 5 + 0] + (flies[i * 5 + 2] + wob * fixed(0.015)) * fixed(dt));
    flies[i * 5 + 1] = fract(flies[i * 5 + 1] + (wob - fixed(0.5)) * fixed(dt) * fspd * fixed(0.12));
  }
}

vec3 shade(Led led) {
  fixed px = fixed(led.pos.x);
  fixed pz = fixed(led.pos.z);
  fixed py = fixed(led.pos.y);
  fixed ang = atan2(pz, px) + fixed(0.5);      // turns, 0..1 (cached per LED)
  fixed best = fixed(0.0);
  for (int i = 0; i < 16; i = i + 1) {
    fixed sd = flies[i * 5 + 4];
    fixed dy = abs(py - flies[i * 5 + 0]);
    fixed da = abs(ang - flies[i * 5 + 1]);
    da = min(da, fixed(1.0) - da);             // wrap angular distance
    fixed dd = sqrt(dy * dy + da * da * fr * fr * ftwo * ftwo);
    fixed tw = sin(head * fixed(3.0) + sd * fixed(12.566));
    fixed on = step(fixed(0.55), fract(sd * fixed(11.17) + head * fixed(0.35)));
    fixed b = on * max(fixed(0.0), fixed(1.0) - dd * fixed(18.0)) * (fixed(0.5) + tw * fixed(0.5));
    best = max(best, b);
  }
  fixed awake = step(fixed(0.5), fdens);       // density gate (cheap global dim)
  fixed h = fract(fwarm * fixed(0.13) + sd0);
  return hsv2rgb(h, fixed(0.55), fixed(1.0)) * (best * fglow * awake);
}

